CREATE POLICY "assets require owned project" ON public.assets AS RESTRICTIVE FOR ALL TO authenticated USING (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id = assets.project_id AND p.user_id = auth.uid())) WITH CHECK (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id = assets.project_id AND p.user_id = auth.uid()));
CREATE POLICY "clips require owned references" ON public.timeline_clips AS RESTRICTIVE FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.projects p WHERE p.id = timeline_clips.project_id AND p.user_id = auth.uid()) AND (asset_id IS NULL OR EXISTS (SELECT 1 FROM public.assets a WHERE a.id = timeline_clips.asset_id AND a.user_id = auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM public.projects p WHERE p.id = timeline_clips.project_id AND p.user_id = auth.uid()) AND (asset_id IS NULL OR EXISTS (SELECT 1 FROM public.assets a WHERE a.id = timeline_clips.asset_id AND a.user_id = auth.uid())));